class BlankNodeReferenceJsonRoundTripTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void tupleJsonPreservesCanonicalBlankNodeId() throws Exception {
		BNode expected = VF.createBNode("bnode1");
		Value actual = roundTrip(expected);

		BNode parsed = assertInstanceOf(BNode.class, actual);
		assertEquals(expected.getID(), parsed.getID());
	}

	@Test
	void tupleJsonPreservesBlankNodeIdsInsideNestedTripleTerms() throws Exception {
		TripleTerm inner = VF.createTripleTerm(VF.createBNode("nested-bnode-2"), VF.createIRI("urn:inner"),
				VF.createBNode("nested-bnode-3"));
		TripleTerm expected = VF.createTripleTerm(VF.createBNode("bnode1"), VF.createIRI("urn:outer"), inner);

		TripleTerm actual = assertInstanceOf(TripleTerm.class, roundTrip(expected));
		assertEquals(expected, actual);
		assertEquals("bnode1", ((BNode) actual.getSubject()).getID());
		TripleTerm actualInner = assertInstanceOf(TripleTerm.class, actual.getObject());
		assertEquals("nested-bnode-2", ((BNode) actualInner.getSubject()).getID());
		assertEquals("nested-bnode-3", ((BNode) actualInner.getObject()).getID());
	}

	private static Value roundTrip(Value value) throws Exception {
		List<String> bindingNames = List.of("value");
		TupleQueryResult result = new IteratingTupleQueryResult(bindingNames,
				List.of(new ListBindingSet(bindingNames, value)));
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		QueryResultIO.writeTuple(result, TupleQueryResultFormat.JSON, output);
		QueryResultCollector collector = new QueryResultCollector();
		QueryResultIO.parseTuple(new ByteArrayInputStream(output.toByteArray()), TupleQueryResultFormat.JSON,
				collector, VF);
		return collector.getBindingSets().get(0).getValue("value");
	}
}
